def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    opp = [h[1] for h in history]
    me = [h[0] for h in history]
    opp_c = opp.count('C')
    opp_d = n - opp_c
    my_c = me.count('C')
    my_d = n - my_c
    last_me = me[-1]
    last_opp = opp[-1]

    # Defect streak tracking for opponent
    streak = 0
    for a in reversed(opp):
        if a == 'D':
            streak += 1
        else:
            break

    # Endgame: if opponent very cooperative, exploit strongly in final rounds
    if n >= 96:
        if opp_c * 2 >= n:
            return 'D'
        return 'C'
    if n >= 90:
        if opp_c * 4 >= n * 3:
            if rng.random() < 0.7:
                return 'D'
        if last_opp == 'D':
            return 'D'
        return 'C'

    # Very cooperative opponent mid-game: mostly cooperate, occasional exploitation
    if n >= 20 and opp_c >= n - n // 10:
        if last_opp == 'D':
            return 'D'
        if rng.random() < 0.06:
            return 'D'
        return 'C'

    # Almost always-defecting opponent
    if n >= 8 and opp_d >= n - 1:
        if rng.random() < 0.05:
            return 'C'
        return 'D'

    # Response to immediate defection
    if last_opp == 'D':
        if last_me == 'D':
            # stuck in DD; try to reset occasionally
            if streak >= 4 and rng.random() < 0.25:
                return 'C'
            return 'D'
        # exploited while cooperating: retaliate
        if streak >= 3:
            if rng.random() < 0.1:
                return 'C'
            return 'D'
        return 'D'

    # last_opp == 'C'
    # recent cooperation rate
    window = 15 if n >= 15 else n
    recent_opp = opp[-window:]
    recent_c = recent_opp.count('C')
    recent_rate = recent_c / window

    if n < 6:
        # early: cooperate, but if opponent defected once already, retaliate
        if opp_d >= 1 and last_opp == 'C':
            return 'C'
        if last_me == 'D' and last_opp == 'C':
            return 'C'
        return 'C'

    # Opponent defected recently but just cooperated - forgive mildly
    if recent_rate >= 0.8:
        # very cooperative recently
        if my_d > my_c and rng.random() < 0.1:
            return 'C'
        if rng.random() < 0.05:
            return 'D'
        return 'C'

    if recent_rate >= 0.5:
        # moderate - tit-for-tat with mild noise
        if last_me == 'D' and rng.random() < 0.7:
            return 'C'
        return 'C'

    # Opposition mostly defecting recently - defend, probe occasionally
    if rng.random() < 0.15:
        return 'C'
    return 'D'
